#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

int bitCount(unsigned int n) {
    int count = 0;
    while (n) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}

ll modExp(ll base, ll exp, ll mod) {
    ll res = 1;
    base %= mod;
    while (exp) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

class HallChecker {
public:
    vector<vector<int>> dp;
    vector<int> maxMatch;
    int stateCount;
    int sizeN;

    HallChecker(int n) : sizeN(n), stateCount(0) {
        dp.resize(1 << n, vector<int>(1, 0));
        maxMatch.resize(1 << n, -1);
    }

    int addState(const vector<bool>& state) {
        int id = findState(state);
        if (id == -1) {
            id = stateCount++;
            dp[id] = vector<int>(state.size());
            for (size_t i = 0; i < state.size(); ++i) {
                dp[id][i] = state[i] ? 1 : 0;
            }
        }
        return id;
    }

private:
    int findState(const vector<bool>& state) {
        for (int i = 0; i < stateCount; ++i) {
            bool eq = true;
            for (size_t j = 0; j < state.size() && eq; ++j) {
                eq = (dp[i][j] == state[j]);
            }
            if (eq) return i;
        }
        return -1;
    }
};

void preCalc(int n, HallChecker& hc) {
    int N = 1 << n;
    vector<vector<bool>> fixedSize(n + 1);
    for (int i = 0; i <= n; ++i) {
        fixedSize[i].resize(N, false);
    }

    for (int mask = 0; mask < N; ++mask) {
        int bits = bitCount(mask);
        fixedSize[bits][mask] = true;
    }

    vector<vector<bool>> states;
    states.push_back(vector<bool>(N, false));
    states.back()[0] = true;

    vector<vector<int>> nextTrans(N, vector<int>());

    for (int k = 0; k < (int)states.size(); ++k) {
        vector<vector<bool>> predHall(n, vector<bool>(N, false));
        for (int mask = 0; mask < N; ++mask) {
            if (states[k][mask]) {
                for (int i = 0; i < n; ++i) {
                    predHall[i][mask | (1 << i)] = true;
                }
            }
        }

        nextTrans[k].resize(N);
        for (int mask = 0; mask < N; ++mask) {
            vector<bool> nextState(N, false);
            for (int i = 0; i < N; ++i) nextState[i] = states[k][i];

            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    for (int j = 0; j < N; ++j) {
                        if (predHall[i][j]) nextState[j] = true;
                    }
                }
            }
            nextTrans[k][mask] = hc.addState(nextState);
        }

        for (int i = n; i >= 0; --i) {
            for (int j = 0; j < N; ++j) {
                if (states[k][j] && fixedSize[i][j]) {
                    hc.maxMatch[k] = i;
                    break;
                }
            }
            if (hc.maxMatch[k] != -1) break;
        }
    }
}

int main() {
    int n, m;
    cin >> n;
    m = n;

    HallChecker hc(n);
    preCalc(n, hc);

    vector<vector<ll>> prob(n, vector<ll>(m));
    ll inv100 = modExp(100, MOD - 2, MOD);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            ll x;
            cin >> x;
            prob[i][j] = (x * inv100) % MOD;
        }
    }

    int N = 1 << n;
    vector<ll> prevState(hc.stateCount, 0), curState(hc.stateCount, 0);
    prevState[0] = 1;

    for (int col = 0; col < m; ++col) {
        fill(curState.begin(), curState.end(), 0);
        for (int mask = 0; mask < N; ++mask) {
            ll pMask = 1;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) {
                    pMask = (pMask * prob[i][col]) % MOD;
                } else {
                    pMask = (pMask * (MOD - prob[i][col])) % MOD;
                }
            }

            for (int k = 0; k < hc.stateCount; ++k) {
                if (prevState[k] == 0) continue;
                int nextIdx = hc.nextTrans[k][mask];
                curState[nextIdx] = (curState[nextIdx] + pMask * prevState[k]) % MOD;
            }
        }
        prevState = curState;
    }

    ll ans = 0;
    for (int k = 0; k < hc.stateCount; ++k) {
        if (hc.maxMatch[k] == n) {
            ans = (ans + prevState[k]) % MOD;
        }
    }
    cout << (ans % MOD + MOD) % MOD << endl;

    return 0;
}
